Sure! Below is a complete example of a Qt5 C++ application that prompts the user to select a directory, then converts all Microsoft Excel files (`.xls` or `.xlsx`) found in that directory into CSV files, saving them in a new subfolder.

### Key points and considerations:
- Qt itself does not provide native Excel file reading capabilities.
- We'll use **Qt's `QAxObject`** to automate Excel via COM on Windows (so this solution works only on Windows with MS Excel installed).
- The app creates a subfolder named `csv_output` inside the chosen directory to store CSV files.
- Supports both `.xls` and `.xlsx`.

If you want a cross-platform solution, you'd need a third-party library like `libxls` or `xlnt` or convert files externally, but with Qt and `QAxObject` this is straightforward on Windows.

---

### 1. Pro `.QAxObject` approach: (Windows-only)

---

### Complete example:

**main.cpp**

```cpp
#include <QApplication>
#include <QWidget>
#include <QPushButton>
#include <QVBoxLayout>
#include <QFileDialog>
#include <QMessageBox>
#include <QDir>
#include <QDebug>
#include <QFileInfoList>
#include <QFileInfo>

#ifdef Q_OS_WIN
#include <ActiveQt/QAxObject>
#else
#error "This example requires Windows with Excel installed."
#endif

class ExcelConverter : public QWidget
{
    Q_OBJECT
public:
    ExcelConverter(QWidget *parent = nullptr) : QWidget(parent)
    {
        auto *layout = new QVBoxLayout(this);
        auto *btnSelectDir = new QPushButton("Select Directory and Convert Excel files", this);
        layout->addWidget(btnSelectDir);

        connect(btnSelectDir, &QPushButton::clicked, this, &ExcelConverter::selectAndConvert);
    }

private slots:
    void selectAndConvert()
    {
        QString dirPath = QFileDialog::getExistingDirectory(this, tr("Select Directory"), QString(),
                                                            QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks);
        if (dirPath.isEmpty())
            return;

        QDir dir(dirPath);
        QStringList filters;
        filters << "*.xls" << "*.xlsx";
        QFileInfoList excelFiles = dir.entryInfoList(filters, QDir::Files | QDir::NoSymLinks);

        if (excelFiles.isEmpty()) {
            QMessageBox::information(this, tr("No Excel files"), tr("No Excel files found in selected directory."));
            return;
        }

        // Create output folder
        QString outFolderName = "csv_output";
        QString outFolderPath = dir.absoluteFilePath(outFolderName);

        QDir outDir;
        if (!outDir.exists(outFolderPath)) {
            if (!dir.mkdir(outFolderName)) {
                QMessageBox::critical(this, tr("Error"), tr("Failed to create output directory."));
                return;
            }
        }

        bool anyFailures = false;

#ifdef Q_OS_WIN
        QAxObject excel("Excel.Application");
        if (excel.isNull())
        {
            QMessageBox::critical(this, tr("Error"), tr("Cannot start Excel."));
            return;
        }
        excel.setProperty("Visible", false);
        excel.setProperty("DisplayAlerts", false);
#else
        QMessageBox::critical(this, tr("Unsupported"), tr("This example only supports Windows."));
        return;
#endif

        for (const QFileInfo &fileInfo : excelFiles)
        {
            QString fullPath = fileInfo.absoluteFilePath();
            QString baseName = fileInfo.completeBaseName();
            QString csvFilePath = outDir.absoluteFilePath(outFolderPath + "/" + baseName + ".csv");

#ifdef Q_OS_WIN
            QAxObject *workbooks = excel.querySubObject("Workbooks");
            if (!workbooks) {
                anyFailures = true; 
                continue;
            }
            QAxObject *workbook = workbooks->querySubObject("Open(const QString&)", fullPath);
            if (!workbook) {
                anyFailures = true;
                continue;
            }

            QVariant csvFormat = QVariant(6); // xlCSV format is 6

            // Save as CSV
            workbook->dynamicCall("SaveAs(const QString&, int)", csvFilePath, csvFormat);

            workbook->dynamicCall("Close()");
            workbooks->dynamicCall("Close()"); // Close all workbooks?
            delete workbook;
            delete workbooks;
#endif
        }

#ifdef Q_OS_WIN
        excel.dynamicCall("Quit()");
#endif

        QString msg = anyFailures ? tr("Some files failed to convert.") : tr("All files converted successfully.");
        QMessageBox::information(this, tr("Done"), msg);
    }
};

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);
    ExcelConverter w;
    w.setWindowTitle("Excel to CSV Converter");
    w.resize(300, 100);
    w.show();
    return app.exec();
}

#include "main.moc"
```

---

### Explanation of the code:

- `QWidget` with a single button.
- Button click opens a folder selection dialog.
- Lists all `.xls` and `.xlsx` files in the selected folder.
- Creates a subfolder `csv_output` in that directory.
- Opens Excel via `QAxObject`.
- Opens each Excel file and saves it as CSV using Excel's own `SaveAs` method with format code `6`.
- Closes Excel, shows a message if any failure happened or success.

---

### How to compile

Make sure your `.pro` file includes:

```
QT       += core gui axcontainer widgets

TARGET = excel_to_csv_qt
TEMPLATE = app

SOURCES += main.cpp
```

Run `qmake` and `make` on Windows.

---

### Important notes:

- This example **works only on Windows** where Microsoft Excel is installed because QAxObject relies on Microsoft COM automation.
- If your development environment or target platform differs, you may need a different approach (e.g., calling Python scripts, using dedicated Excel libraries, or third-party tools).

---

Let me know if you want a cross-platform solution or have additional requirements!

